function byId(rows) {
  const map = new Map(rows.map(row => [row.pair_id,row]));
  assert.equal(map.size,rows.length);
  assert.deepEqual([...map.keys()].sort(),pairs.map(row=>row.pair_id).sort());
  return map;
}
function calculate(referenceRows, guideRows) {
  const r = byId(referenceRows), g = byId(guideRows);
  const metrics = {eligible_time_pairs:0,reference_seconds:0,guide_seconds:0,time_saved_seconds:0,
    faster_pairs:0,slower_pairs:0,tied_pairs:0,accuracy_pairs:0,reference_correct:0,guide_correct:0};
  const timedIds = [], missingIds = [];
  for(const pair of pairs) {
    const a = r.get(pair.pair_id), b = g.get(pair.pair_id);
    for (const record of [a,b]) {
      assert.ok(['true','false'].includes(record.correct));
      assert.ok(['true','false'].includes(record.assisted));
      assert.ok(record.seconds === '' || (Number.isFinite(Number(record.seconds)) && Number(record.seconds) > 0));
    }
    metrics.accuracy_pairs++;
    metrics.reference_correct += Number(a.correct === 'true');
    metrics.guide_correct += Number(b.correct === 'true');
    if(a.seconds === '' || b.seconds === '') {missingIds.push(pair.pair_id); continue;}
    const delta = Number(a.seconds)-Number(b.seconds);
    metrics.eligible_time_pairs++;
    metrics.reference_seconds += Number(a.seconds);
    metrics.guide_seconds += Number(b.seconds);
    metrics.time_saved_seconds += delta;
    metrics[delta > 0 ? 'faster_pairs' : delta < 0 ? 'slower_pairs' : 'tied_pairs']++;
    timedIds.push(pair.pair_id);
  }
  return {metrics,timedIds,missingIds};
}
